import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"FRITZ!Box to MQTT","text":"Application Home Assistant pour les données FRITZ!Box","tagline":"Intégration des journaux d'appels, des appels en temps réel, du Wi-Fi, du WAN, des répertoires téléphoniques et de l'état de la FRITZ!Box dans Home Assistant via la découverte MQTT (MQTT Discovery).","actions":[{"theme":"brand","text":"Installation","link":"/fr/projects/fritzbox-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons"}]},"features":[{"icon":"📞","title":"Appels et répondeurs","details":"Journaux d'appels, suivi des appels en temps réel et répondeurs (de AB0 à AB4) disponibles en tant qu'entités dans Home Assistant."},{"icon":"📶","title":"Wi-Fi et réseau","details":"Contrôles pour les réseaux Wi-Fi 2,4 GHz, 5 GHz et invité, ainsi que les données de connexion WAN, les adresses IP et l'état des liaisons."},{"icon":"📚","title":"Répertoires téléphoniques","details":"Répertoires téléphoniques avec affichage sélectionnable et possibilité d'exclure certains noms."},{"icon":"🧭","title":"Sources de données multiples","details":"Combinaison de TR-064, des mécanismes de secours (fallbacks) via l'interface Web/Lua de la FRITZ!Box et du moniteur d'appels en temps réel."},{"icon":"🏠","title":"Découverte MQTT (MQTT Discovery)","details":"Home Assistant crée automatiquement les capteurs et les interrupteurs grâce à la découverte MQTT."},{"icon":"🛠️","title":"Dépannage","details":"Page dédiée au dépannage pour la connexion, TR-064, DNS over TLS, le moniteur d'appels et MQTT."}]},"headers":[],"relativePath":"fr/projects/fritzbox-to-mqtt/index.md","filePath":"fr/projects/fritzbox-to-mqtt/index.md","lastUpdated":1793123188000}`),o={name:"fr/projects/fritzbox-to-mqtt/index.md"};function n(r,e,l,d,p,c){return s(),i("div",null,[...e[0]||(e[0]=[a('<p><a id="index"></a><a id="statut"></a></p><h2 id="uberblick" tabindex="-1">Aperçu <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Aperçu {#uberblick}&quot;">​</a></h2><p>« FRITZ!Box to MQTT » est une application pour Home Assistant qui intègre des données provenant d&#39;une FRITZ!Box dans Home Assistant via la découverte MQTT.</p><p>La version actuelle de l&#39;add-on est disponible dans le dépôt commun <code>rockbaer2007/ugso-ha-mqtt-addons</code>. L&#39;ancien dépôt dédié <code>rockbaer2007/fritzbox-to-mqtt</code> est désormais archivé.</p><p>L&#39;application utilise plusieurs sources, car les interfaces disponibles peuvent varier d&#39;une FRITZ!Box à l&#39;autre :</p><ul><li>TR-064 pour de nombreux services de la FRITZ!Box</li><li>Requêtes via l&#39;interface Web/Lua de la FRITZ!Box en guise de solution de secours (fallback)</li><li>Le moniteur d&#39;appels en temps réel sur le port <code>1012</code></li><li>La découverte MQTT pour la création automatique d&#39;entités dans Home Assistant</li></ul><div class="info custom-block"><p class="custom-block-title">HACS</p><p>Ce projet est une application pour le « Supervisor » de Home Assistant. HACS permet d&#39;installer des intégrations personnalisées et des cartes d&#39;interface (frontend cards), mais ne prend pas en charge les applications basées sur Docker (Supervisor apps). L&#39;installation doit donc s&#39;effectuer via la fonctionnalité de dépôt d&#39;applications de Home Assistant. :::</p><h2 id="weitere-seiten" tabindex="-1">Autres pages <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Autres pages {#weitere-seiten}&quot;">​</a></h2><ul><li><a href="/fr/projects/fritzbox-to-mqtt/installation">Installation</a></li><li><a href="/fr/projects/fritzbox-to-mqtt/configuration">Configuration</a></li><li><a href="/fr/projects/fritzbox-to-mqtt/entities">Entités</a></li><li><a href="/fr/projects/fritzbox-to-mqtt/examples">Exemples</a></li><li><a href="/fr/projects/fritzbox-to-mqtt/troubleshooting">Dépannage</a></li></ul></div>',7)])])}const f=t(o,[["render",n]]);export{m as __pageData,f as default};
